import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"A Survey of Robotic Navigation and Manipulation with Physics Simulators in the Era of Embodied AI","description":"","frontmatter":{"title":"A Survey of Robotic Navigation and Manipulation with Physics Simulators in the Era of Embodied AI","arxiv":"2505.01458","date":"2025-05-01","authors":"Lik Hang Kenny Wong, Xueyang Kang, Kaixin Bai, Jianwei Zhang","categories":"cs.RO, cs.AI","topics":"具身智能综述, 物理仿真器, sim-to-real","outline":[2,2]},"headers":[],"relativePath":"papers/2505.01458.md","filePath":"papers/2505.01458.md","lastUpdated":null}'),l={name:"papers/2505.01458.md"};function e(i,s,m,r,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="a-survey-of-robotic-navigation-and-manipulation-with-physics-simulators-in-the-era-of-embodied-ai" tabindex="-1">A Survey of Robotic Navigation and Manipulation with Physics Simulators in the Era of Embodied AI <a class="header-anchor" href="#a-survey-of-robotic-navigation-and-manipulation-with-physics-simulators-in-the-era-of-embodied-ai" aria-label="Permalink to &quot;A Survey of Robotic Navigation and Manipulation with Physics Simulators in the Era of Embodied AI&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2505.01458" target="_blank" rel="noreferrer">2505.01458</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-05-01</td></tr><tr><td><strong>作者</strong></td><td>Lik Hang Kenny Wong, Xueyang Kang, Kaixin Bai, Jianwei Zhang</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>不按&quot;仿真器功能清单&quot;而按&quot;哪些底层物理/传感属性真正决定 sim-to-real 结果&quot;来重组导航与操作综述，并把仿真诱发的失败模式做成可排查的分类表。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>具身智能的两大核心能力是导航与操作，而两者的训练几乎都依赖仿真——真实世界采数据昂贵、耗时且不安全。问题是仿真里的排名并不可靠地预测真机上的排名。作者把这件事形式化：给定策略 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span> 与越大越好的任务指标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span></span></span></span>，sim-to-real gap 定义为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">G</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">sim</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">real</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">)</span></span></span></span>；但更值得关心的不是绝对差值，而是<strong>预测性</strong>——在仿真里排名高的方法是否在硬件上也排名高，这可以用 Sim-to-Real Correlation Coefficient (SRCC) 来度量。</p><p>论文要回答的是三个很实用的问题：哪些仿真器属性对不同任务最关键；哪些 sim-to-real gap 被现有仿真器捕捉、缓解或遗留；研究者该如何在硬件约束下选方法、配仿真器。它的重要性在于视角的转换——大多数综述在比较&quot;支持哪些功能&quot;，本文在比较&quot;哪些底层建模选择会改变结论&quot;，因为后者才是让一篇论文在真机上翻车的原因。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>早期的具身智能仿真器与导航综述（Duan et al. 2022；Zhu et al. 2021）成文于大语言模型与 world model 兴起之前，无法覆盖近年的方法学变化。另一类综述提供宽泛的 EAI 概览或聚焦特定方法论（如基础模型），但没有从物理仿真器属性的角度同时贯通导航与操作。</p><p>作者对这些工作的批评是精确的：现有关于仿真器选择的讨论要么停留在定性描述，要么只在仿真内部比较，很少触及<strong>低层仿真器属性</strong>——接触/冲击建模公式、积分器与求解器设置、驱动时序、传感器模型。而恰恰是这些属性决定了 sim-to-real 的结果。论文用一张证据表把这一点钉死：Kadian et al. 显示调过的碰撞响应把 SRCC(SPL) 从 0.603 提到 0.875；Collins et al. 显示接触求解器的选择让位姿误差从 133.61（V-REP Bullet 2.78）降到 45.46（V-REP Newton）；Kataoka et al. 显示加入噪声与插值的驱动时序建模让真实装配成功率从 0% 变成 50%。三个例子分别落在碰撞、接触求解器、驱动时序上，共同说明&quot;两个方法在仿真里看起来差不多，迁移到硬件却完全不同&quot;是常态而非例外。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>不用本文的贡献做前提，可以这样重建。首先，一个已被反复观察到的现象是：导航智能体会利用碰撞响应的伪影（贴墙滑行、切角）来提高 SPL，视觉策略会因为光照、纹理、干扰物、相机扰动而失效，四足运动策略会因为延迟、驱动器、足-地接触失配而在硬件上漂移。这些不是同一类错误，但它们有一个共同结构：<strong>策略学到了仿真器的某个建模选择，而不是任务本身</strong>。</p><p>其次，社区通常用一张&quot;功能对勾表&quot;来选仿真器（支持刚体、支持布料、支持光追）。但打勾并不等于&quot;该现象被建模到目标任务所需的保真度&quot;。作者在文中直接点破：「支持 cloth/soft body」不应被理解为「已验证可迁移的叠衣服 sim-to-real」，因为可形变操作还依赖材料辨识、自接触处理、摩擦、阻尼、传感与控制器接口的真实性。</p><p>第三，缓解手段其实只有三大类：标定与显式建模（传感器噪声、延迟、驱动器标定、质量/摩擦/阻尼/增益的系统辨识）；随机化（视觉域随机化与动力学随机化）；面向迁移的策略学习（鲁棒优化、域自适应、残差学习、在线自适应）。既然手段有限，选择就归结为&quot;我这个任务里哪些属性必须被建模、哪些可以被随机化掉&quot;。</p><p>顺着这三步，综述的组织方式就自然从&quot;按仿真器列举&quot;变成&quot;按属性—任务—失败模式对应&quot;。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>仿真器不是任务的中立容器，而是策略会去利用的一组建模假设。决定迁移成败的往往不是渲染有多漂亮或支持多少种物理现象，而是<strong>任务所依赖的那几个低层属性是否被建模到足够保真度</strong>——导航依赖碰撞响应与几何，腿足系统额外依赖驱动时序与全身接触，操作依赖接触求解器与材料参数。因此正确的问法不是&quot;这个仿真器好不好&quot;，而是&quot;我这个任务会因为哪个属性失配而失败，我该标定它、随机化它，还是显式测它&quot;。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>综述本身没有&quot;方法&quot;，但它给出的<strong>选型与排查流程</strong>可以当作 pipeline 来用。以&quot;训练一个抓取并放置的操作策略&quot;为例：</p><ul><li><strong>定位任务的关键属性</strong>。接触是否密集？物体是否可形变或易碎？需要触觉吗？作者按复杂度与自由度把操作任务排成谱系：抓取 → 灵巧操作（in-hand 重定向、finger gaiting）→ 可形变物体操作 → 易碎物体操作（接触载荷上界是损坏阈值、下界是防滑最小值）→ 移动操作 → 开放世界操作 → 双臂操作。</li><li><strong>按属性而非按功能选仿真器</strong>。表 3 是决策导向的：MuJoCo 接触建模强、驱动器模型丰富、适合接触密集控制与系统辨识，但传感真实性低、存在互穿、布料 sim-to-real 缺乏验证；Isaac Sim / Isaac Lab 视觉与部署友好、适合合成数据与大规模 GPU RL；Gazebo 与 CoppeliaSim 因深度集成 ROS 而适合面向部署的工作流；可形变任务则应优先考虑 SoftGym、PlasticineLab、基于 IPC 的抓取仿真器等专用工具。</li><li><strong>选择传感模态并明确它约束了什么</strong>。作者把模态按&quot;提供什么信息&quot;分三类：纯视觉给全局场景与几何，适合接触前的规划，但图像主要观测外部几何而非内部接触状态，抓取稳定阶段的初始滑移、法向/切向力、过度挤压都可能在出现明显视觉线索之前就导致失败；纯接触（力/力矩、关节力矩、触觉）给接触界面状态，天然对接阻抗或力位混合控制，但缺乏接触前的搜索与对齐信息、对安装与标定漂移敏感；视触融合则要决定&quot;哪个模态在哪个阶段、以什么带宽主导行为&quot;——RDP 用慢速视觉扩散策略产生粗动作块、用快速触觉/力通路在块内高频修正，是这一思路的代表。</li><li><strong>选策略族并核对真正的瓶颈</strong>。表 5 强调参数量不决定可及性：RL 的瓶颈是 rollout 成本，model-based RL 是在线规划，扩散策略是去噪步数决定的推理延迟，VLM/VLA 是显存与微调成本。低资源下 BC 与 ACT 式模仿最可及。</li><li><strong>按失败签名排查而非只看成功率</strong>。表 6 把失配源、失败签名、检查手段一一对应：几何/碰撞失配表现为贴墙滑行、切角、SPL 很高但接触不安全，应记录接触、间隙与路径偏差并做 sim-real 排名一致性检验；观测/传感失配表现为在光照、纹理、深度、视场、模糊、延迟变化下 grounding 失败，应做因子化的 corruption 测试；动力学/驱动/时序失配表现为打滑、摔倒、振荡、过冲、失同步，或只在理想化 API 下才成功，应比较指令与实测状态及时间戳；刚体接触/材料失配表现为抓取打滑、穿透、粘滞或弹跳、插入卡死；可形变/易碎/触觉失配表现为褶皱、打结、断裂阈值或触觉图像不可迁移；最后一类是<strong>评测伪影</strong>——相近的 SR/SPL 掩盖了不同的碰撞、力、滑移裕度或鲁棒性。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>综述的形式化集中在 sim-to-real 定义与导航指标，它们的共同 intuition 是&quot;如何把&#39;完成了&#39;与&#39;完成得对&#39;区分开&quot;。</p><p>sim-to-real gap 已在 §1 给出：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">G</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">sim</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">real</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">)</span></span></span></span>。作者强调仿真器还应当具有<strong>预测性</strong>，即仿真中的排名应与硬件排名一致，用 SRCC 度量。</p><p>导航侧最常用的效率指标是 SPL：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">SPL</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">max</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 是 episode 数，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是成功指示，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是最短路径长度，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是实际路径长度。分母取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mop">max</span></span></span></span> 保证走得比最短路还短不会被奖励，因此 SPL 是&quot;成功率乘以路径效率&quot;的乘性折扣。它的盲区正是本文关心的：一个智能体可以靠贴墙滑行缩短 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 从而抬高 SPL，而这条路径在真机上根本走不通。</p><p>任务驱动导航需要比较预测路径与参考路径。CLS 定义为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">CLS</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">PC</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">LS</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mclose">)</span></span></span></span>，路径覆盖率乘以长度得分；nDTW 则同时考虑空间对齐与动作顺序，给出 0 到 1 的相似度。两者都通过按参考路径长度归一化来获得尺度不变性。作者引用 Jain et al. 的诊断实验说明为什么需要它们：一个面向保真度的奖励能大幅提升 CLS，而 SR 与 SPL 只在很窄的区间内变化——<strong>目标完成度与指令忠实度会分离</strong>。</p><p>EQA 的效率指标把答案正确性与探索效率相乘：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">4</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.3074em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">max</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">100%</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6891em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span><span class="mclose">]</span></span></span></span> 是 LLM-Match 打分，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mord">/4</span></span></span></span> 把它归一化到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>。安全侧则用 IVR = 违规 episode 数 / 总 episode 数来量化对常识约束（如乱穿马路）的违反。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>综述不做新实验，但它组织了一批<strong>关键证据</strong>来支撑核心论点，可以按&quot;问题—证据—结论&quot;读。</p><p>问题一：低层物理与传感选择真的会改变 sim-to-real 结论吗？证据是表 1 的三条：碰撞响应调优使 SRCC(SPL) 从 0.603 升到 0.875；接触引擎从 V-REP Bullet 2.78 换成 V-REP Newton 使位姿误差从 133.61 降到 45.46；加入噪声与插值的驱动时序建模使真实装配成功率从 0% 变成 50%。结论是：仿真预测性对底层建模选择高度敏感，这不是二阶效应。</p><p>问题二：学习到的 world model 能否替代解析仿真器？作者在同一张表里放了 world model 的证据：PIN-WM 配合物理感知数字表亲（PADC）的真实推动成功率 75%，而 RoboGSim 为 30%；PhysWorld 的真实视频 Chamfer Distance 为 0.010，PhysTwin 为 0.012。结论有两面：物理先验确实能改善受限域内的迁移与预测保真度；但 world model 从有限数据学得、常绑定于特定任务分布与观测空间，无法像解析仿真器那样提供用户可控的几何、动力学、材料、传感配置与接触参数。</p><p>问题三：现有评测是否足以判断可部署性？作者的结论是否定的，并给了具体的混淆例子：两个导航智能体可能 SPL 相近但碰撞响应与安全间隙不同；两个运动策略可能仿真回报相近但硬件漂移与摔倒率不同；两个操作策略可能仿真成功率相近但接触力、滑移裕度、形变行为、对材料变化的鲁棒性不同。文中还引用 SAFEMANIP 的结果指出，操作任务成功率的提升并不可靠地转化为时序安全性的提升，很多成功的 rollout 其实是不安全的。因此建议报告接触率、间隙、力/滑移裕度、扰动鲁棒性与 sim-real 预测性，而不只是成功率。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：本文以&quot;仿真器属性如何影响学习、评测与部署&quot;为主线，重新组织了导航与操作两条线的任务、仿真器、数据集、指标与方法。它把 sim-to-real 差距拆成感知差距与动作-动力学差距，并把缓解手段归为标定/显式建模、随机化、面向迁移的策略学习三类。它用三条实证（碰撞响应影响 SRCC、接触求解器影响位姿误差、驱动时序影响真实装配成功率）证明低层建模选择足以颠覆结论。它给出决策导向的仿真器对比与仿真诱发失败的分类表，把&quot;失配源—失败签名—检查手段&quot;配成可操作的排查流程。它主张评测必须超越成功率，报告安全裕度、力/滑移裕度与 sim-real 预测性。</p><p><strong>3 句话版</strong>：仿真器不是中立容器，策略会学到它的建模假设。选型应按任务依赖的低层属性来做，而不是按功能对勾表。成功率会掩盖不同的失败模式，评测需要报告过程性与安全性指标。</p><p><strong>1 句话版</strong>：把&quot;选哪个仿真器&quot;重述为&quot;我的任务会因为哪个物理属性失配而失败&quot;。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是贯穿全文的<strong>可分解性假设</strong>：sim-to-real gap 可以被拆成一组相对独立的属性（碰撞响应、接触求解器、驱动时序、传感噪声、材料参数），逐个诊断、逐个缓解，整体迁移就会改善。整篇综述的实用价值——那张&quot;失配源 → 失败签名 → 检查/缓解&quot;的表——完全建立在这条假设上。</p><p>它在实践中很可能不成立，因为这些属性是耦合的：接触求解器的选择会改变有效摩擦与穿透，进而改变足-地反馈时序，进而改变控制器该如何标定；把某一项随机化以获得鲁棒性，可能会让策略对另一项过度保守。更麻烦的是失败签名本身不唯一——&quot;抓取打滑&quot;可以来自摩擦系数错、接触求解器错、触觉模型错、或控制器接口时序错，表格提供的是候选集而非诊断。</p><p>论文为可分解性提供的证据是<strong>单因子实验</strong>：Kadian 只改碰撞响应，Collins 只换接触引擎，Kataoka 只加时序噪声与插值。这些实验恰恰证明了单因子有影响，但没有证明多因子的效应可加或可独立处理。综述缺少的正是交互效应的证据——例如同时失配两个属性时，逐项修正是否单调改善迁移。作者自己也承认同一高层指标会掩盖不同的仿真误差，这其实是在暗示归因困难，但没有把它上升为对可分解性本身的质疑。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、不需要真机的最小验证：检验&quot;低层属性变化是否显著改变方法排名&quot;，即检验本文最核心的经验主张的一个可控切片。</p><ul><li>数据/环境：选一个轻量抓取任务（例如从桌面抓起圆柱体并放入盒中），在两个引擎里各搭一份等价场景（MuJoCo 与 PyBullet），几何、质量、初始位姿完全一致。</li><li>实现：训练三个差异明显的策略——BC、ACT 式动作分块、少步数扩散策略——在引擎 A 上用相同数据训练；然后在引擎 A 与引擎 B 上分别评测（B 充当&quot;另一套物理假设&quot;，替代昂贵的真机）。再做一组变体：只改引擎 A 的摩擦系数与求解器迭代数，其余不变。</li><li>测量：三个策略在各条件下的成功率排名、Spearman 秩相关；同时记录接触力峰值、穿透量、滑移次数这些过程性指标。</li><li>判定：若跨引擎排名的秩相关显著低于 1（例如出现名次互换），则支持&quot;仿真属性会颠覆方法排名&quot;这一主张；若排名稳定而只有绝对成功率平移，则说明属性差异主要影响难度而非排名，本文对评测可靠性的警告需要弱化。附带地，若过程性指标（接触力、滑移）在排名互换前就已经分化，就为&quot;应报告过程性指标&quot;提供了直接支持。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是给出一个<strong>替代解释</strong>：本文列举的迁移失败，也许主要由数据分布与任务规格不匹配造成，而非物理保真度不足；如果是这样，投入去精修接触求解器与时序模型的回报会远低于投入去做更好的域随机化与真实数据微调。</p><p>设计一个能区分的实验：固定一个接触密集任务，构造两条对照路线——路线 A 投入预算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> 去做系统辨识与高保真接触建模（标定摩擦、阻尼、驱动器、延迟），路线 B 用同样预算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> 去做大范围动力学与视觉随机化 + 少量真机数据微调。若路线 B 在同等预算下达到相当或更好的真机成功率，那么&quot;低层属性保真度是关键&quot;这一主张就被削弱为&quot;低层属性只要被随机化覆盖即可，不必被精确建模&quot;——这会显著改变本文给读者的行动建议。</p><p>一类可预测失败的场景也值得指出：本文的失败分类表默认失败签名可观测且可归因。但在长时序移动操作中，早期的微小接触失配会通过场景状态传播，最终表现为一个与初因完全无关的下游失败（例如物体被轻微推偏，导致后续导航目标不可达）。在这类场景中，&quot;失配源 → 失败签名&quot;的映射会退化为多对多，排查表将失去可操作性。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：本文给出了&quot;哪些属性重要&quot;的定性结论与若干单因子证据，但没有给出<strong>在给定预算下应该先标定哪个属性</strong>的定量方法。实践中研究者面对的是资源分配问题，而不是知识问题。</p><p><strong>新的 framing</strong>：把仿真器配置从&quot;工程调参&quot;重述为<strong>主动实验设计</strong>问题。把仿真器的可配置属性（摩擦、阻尼、求解器迭代、延迟、传感噪声、接触刚度）看作一组待推断的参数，把&quot;在真机上跑一次评测&quot;看作一次昂贵的观测，目标是用尽可能少的真机试验，最大化仿真对真机排名的预测性（SRCC）而非最小化单一策略的性能差。这与传统 system identification 的目标不同：后者追求参数精确，前者追求<strong>排名保真</strong>——一个参数即使估得不准，只要不改变方法间的相对次序，就不值得花预算去标定。</p><p><strong>可借鉴的相邻领域工具</strong>：贝叶斯最优实验设计与信息增益准则用于挑选下一次做哪个真机试验；多保真度贝叶斯优化用于在&quot;廉价低保真仿真 / 昂贵高保真仿真 / 极昂贵真机&quot;之间分配预算；排序学习中的成对比较理论用于把目标直接写成排名一致性而非回归误差。</p><p><strong>第一个实验</strong>：不需要真机——用两个引擎构造&quot;伪 sim-real&quot;对（引擎 A 为 sim，引擎 B 为 real 的代理）。取 8–10 个操作策略，先用少量 B 上的成对比较去估计&quot;哪些 A 侧属性最能影响 A、B 排名一致性&quot;，再用主动选择的少量比较去调 A 的属性配置，报告 SRCC 随比较次数增长的曲线，并与&quot;随机选择比较&quot;和&quot;全量标定&quot;两条基线对比。若主动设计能用远少于全量标定的观测达到接近的 SRCC，就说明&quot;为排名保真而标定&quot;是一个比&quot;为参数精确而标定&quot;更经济的目标，这会把本文的定性建议变成可执行的预算分配方案。</p>',54)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
